package main

// Adder is the narrow contract the application needs from its arithmetic
// helper. Keeping it to a single method lets tests substitute a small fake.
type Adder interface {
	Add(a, b int) int
}

// Calculator is the minimal structure that owns the real helper. Exposing the
// helper as a method makes it reachable through the Adder interface.
type Calculator struct{}

// Add returns the sum of a and b.
func (Calculator) Add(a, b int) int {
	return add(a, b)
}

// Service is the application-facing structure. It depends on Adder instead of
// calling the helper directly, so its behaviour can be tested in isolation.
type Service struct {
	adder Adder
}

// NewService wires a Service with the supplied Adder. Callers pass a real
// Calculator in production and a fake in tests.
func NewService(adder Adder) *Service {
	return &Service{adder: adder}
}

// Total adds two numbers through the injected helper.
func (s *Service) Total(a, b int) int {
	return s.adder.Add(a, b)
}

// add holds the actual arithmetic so there is a single implementation.
func add(a, b int) int {
	return a + b
}

func main() {}

