package main

import "testing"

// fakeAdder is a stub that records calls and returns a fixed value. It exists
// only in the test file, which is the point of injecting Adder.
type fakeAdder struct {
	calls int
	value int
}

func (f *fakeAdder) Add(a, b int) int {
	f.calls++
	return f.value
}

func TestServiceTotalUsesInjectedAdder(t *testing.T) {
	fake := &fakeAdder{value: 42}
	svc := NewService(fake)

	if got := svc.Total(2, 3); got != 42 {
		t.Fatalf("Total(2, 3) = %d, want 42", got)
	}
	if fake.calls != 1 {
		t.Fatalf("adder calls = %d, want 1", fake.calls)
	}
}

func TestCalculatorAdd(t *testing.T) {
	tests := []struct {
		name string
		a    int
		b    int
		want int
	}{
		{name: "positive", a: 2, b: 3, want: 5},
		{name: "negative", a: -2, b: 3, want: 1},
		{name: "zero", a: 0, b: 0, want: 0},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := (Calculator{}).Add(tt.a, tt.b); got != tt.want {
				t.Fatalf("Add(%d, %d) = %d, want %d", tt.a, tt.b, got, tt.want)
			}
		})
	}
}

func TestNewServiceAcceptsCalculator(t *testing.T) {
	svc := NewService(Calculator{})
	if got := svc.Total(4, 5); got != 9 {
		t.Fatalf("Total(4, 5) = %d, want 9", got)
	}
}

